import { useState, useContext } from "react";
import { ComplaintContext } from "../context/ComplaintContext";

function AddComplaint() {
  const { addComplaint } = useContext(ComplaintContext);

  const [form, setForm] = useState({
    title: "",
    description: "",
    department: "",
    image: null
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    addComplaint(form);
    alert("Complaint submitted");
  };

  return (
    <form className="form" onSubmit={handleSubmit}>
      <input placeholder="Title" onChange={(e)=>setForm({...form,title:e.target.value})}/>
      <textarea placeholder="Description" onChange={(e)=>setForm({...form,description:e.target.value})}/>
      <select onChange={(e)=>setForm({...form,department:e.target.value})}>
        <option>Roads</option>
        <option>Water</option>
        <option>Electricity</option>
        <option>Sanitation</option>
      </select>
      <input type="file" onChange={(e)=>setForm({...form,image:URL.createObjectURL(e.target.files[0])})}/>
      {form.image && <img src={form.image} width="120"/>}
      <button>Submit</button>
    </form>
  );
}
export default AddComplaint;
